	"slash.todo.usage":
		"用法：/todo <verb> [args]\n  /todo                              显示当前待办\n  /todo edit                         在 $EDITOR 中打开待办\n  /todo copy                         将待办以 Markdown 复制到剪贴板\n  /todo expand                       在 HUD 中显示所有阶段和任务\n  /todo collapse                     恢复有界的 HUD 预览\n  /todo export [<path>]              将待办写入文件（默认：TODO.md）\n  /todo import [<path>]              从文件替换待办（默认：TODO.md）\n  /todo append [<phase>] <task...>   追加任务；阶段通过模糊匹配或自动创建\n  /todo start  <task>                将任务标记为进行中（模糊内容匹配）\n  /todo done   [<task|phase>]        将任务/阶段/全部标记为已完成\n  /todo drop   [<task|phase>]        将任务/阶段/全部标记为已放弃\n  /todo rm     [<task|phase>]        移除任务/阶段/全部",
