	"cli.config.help":
		"{{title}} - 管理设置\n\n{{headingCommands}}\n  list               列出所有设置及其当前值\n  get <key>          获取指定设置的值\n  set <key> <value>  设置某个设置的值\n  reset <key>        从 config.yml 移除某个设置，使其默认值生效\n  path               打印配置目录路径\n  init-xdg           初始化 XDG Base Directory 结构\n\n{{headingOptions}}\n  --json             以 JSON 输出\n\n{{headingExamples}}\n  {{app}} config list\n  {{app}} config get theme\n  {{app}} config set theme catppuccin-mocha\n  {{app}} config set compaction.enabled false\n  {{app}} config set defaultThinkingLevel medium\n  {{app}} config reset steeringMode\n  {{app}} config list --json\n  {{app}} config init-xdg\n\n{{headingBooleanValues}}\n  true, false, yes, no, on, off, 1, 0\n",
	"cli.grep.help":
		'{{title}} - 测试 grep 工具\n\n{{headingUsage}}\n  {{app}} grep <pattern> [path] [options]\n\n{{headingArguments}}\n  pattern   要搜索的正则表达式模式\n  path      要搜索的目录或文件（默认：.）\n\n{{headingOptions}}\n  -g, --glob <pattern>  按 glob 模式过滤文件\n  -l, --limit <n>       最大匹配数（默认：20）\n  -C, --context <n>     上下文行数（默认：2）\n  -f, --files           仅输出文件名\n  -c, --count           输出每个文件的匹配计数\n  -h, --help            显示此帮助\n  --no-gitignore        包含被 .gitignore 排除的文件\n\n{{headingEnvironment}}\n  PI_WALK_WORKERS=N    设置文件系统遍历 worker 数（默认 4，0 = 自动）\n\n{{headingExamples}}\n  {{app}} grep "import" src/\n  {{app}} grep "TODO" . --glob "*.ts"\n  {{app}} grep "function" --files\n',
	"cli.plugin.help":
		"{{title}} - 插件生命周期管理\n\n{{headingCommands}}\n  install <source>[features]     从 npm、GitHub 或 git URL 安装插件\n  uninstall <pkg>                移除插件\n  list                           显示已安装插件\n  link <path>                    链接本地插件用于开发\n  doctor                         检查插件健康状态\n  features <pkg>                 查看/修改已启用功能\n  config <cmd> <pkg> [key] [val] 管理插件设置\n  enable <pkg>                   启用已禁用的插件\n  disable <pkg>                  禁用插件而不卸载\n  marketplace <cmd>            管理 marketplace 源（add、remove、update、list）\n  discover [marketplace]        浏览可用的 marketplace 插件\n\n{{headingFeatureSyntax}}\n  pkg                使用默认功能安装\n  pkg[feat1,feat2]   使用指定功能安装\n  pkg[*]             安装所有功能\n  pkg[]              不安装可选功能\n\n{{headingSources}}\n  pkg, pkg@1.2.3                  npm 包（可选固定版本）\n  github:user/repo[#ref]          GitHub 简写（也支持 gitlab:、bitbucket:、codeberg:、sourcehut:）\n  https://github.com/user/repo    完整 git URL（https、ssh 或 git 协议）\n  name@marketplace                Marketplace 插件（参见 marketplace 命令）\n  ./path, ../path, /abs, ~/path   本地插件目录（符号链接，等同于 plugin link）\n\n{{headingConfigSubcommands}}\n  config list <pkg>              列出所有设置\n  config get <pkg> <key>         获取某个设置的值\n  config set <pkg> <key> <val>   设置某个设置的值\n  config delete <pkg> <key>      删除某个设置\n  config validate                校验所有插件设置\n\n{{headingOptions}}\n  --json           以 JSON 输出\n  --fix            尝试自动修复（doctor）\n  --force          覆盖而不提示（install）\n  --scope <scope>  安装范围：user（默认）或 project（install name@marketplace）\n  --dry-run        预览更改而不应用（install）\n  -l, --local      使用项目本地覆盖\n\n{{headingExamples}}\n  {{app}} plugin install @oh-my-pi/exa[search]\n  {{app}} plugin list --json\n  {{app}} plugin features my-plugin --enable search,web\n  {{app}} plugin config set my-plugin apiKey sk-xxx\n  {{app}} plugin doctor --fix\n  {{app}} plugin install --scope project name@marketplace\n  {{app}} plugin install github:user/repo#v1.0\n",
	"cli.setup.help":
		"{{title}} - 运行入门向导或安装可选功能的依赖\n\n{{headingUsage}}\n  {{app}} setup                     运行入门向导\n  {{app}} setup <component> [options]\n\n{{headingComponents}}\n  python    验证可用于代码执行的 Python 3 解释器是否可访问\n  speech    选择并下载语音转文本和文本转语音模型\n\n{{headingOptions}}\n  -c, --check   检查依赖是否已安装而不安装\n  --json        以 JSON 输出状态\n\n{{headingExamples}}\n  {{app}} setup                  运行入门向导\n  {{app}} setup python           检查 Python 执行依赖\n  {{app}} setup speech           选择并下载 STT 和 TTS 模型\n  {{app}} setup speech --check   检查语音依赖是否可用\n  {{app}} setup python --check   检查 Python 执行是否可用\n",
	"cli.shell.help":
		"{{title}} - 用于测试的交互式 shell 控制台\n\n{{headingUsage}}\n  {{app}} shell [options]\n\n{{headingOptions}}\n  --cwd, -C <path>     设置命令的工作目录\n  --timeout, -t <ms>   每条命令的超时时间（毫秒）\n  --no-snapshot        跳过从用户 shell 加载快照\n  -h, --help           显示此帮助\n\n{{headingExamples}}\n  {{app}} shell\n  {{app}} shell --cwd ./tmp\n  {{app}} shell --timeout 2000\n",
	"cli.update.help":
		"{{title}} - 检查并安装更新\n\n{{headingUsage}}\n  {{app}} update [options]\n\n{{headingOptions}}\n  -c, --check     检查更新而不安装\n  -f, --force     即使已是最新也强制重新安装\n  -l, --plugins   更新已安装插件\n  --canary        切换到 canary 渠道并更新\n  --stable        切换回 stable 渠道\n\n{{headingExamples}}\n  {{app}} update              更新到最新版本\n  {{app}} update --check      检查是否有可用更新\n  {{app}} update --force      强制重新安装\n  {{app}} update -l           更新已安装插件\n  {{app}} update --canary    切换到 canary 渠道并更新\n",
	"cli.webSearch.help":
		'{{title}} - 测试网页搜索模型\n\n{{headingUsage}}\n  {{app}} q [options] <query>\n  {{app}} web-search [options] <query>\n\n{{headingArguments}}\n  query      搜索查询文本\n\n{{headingOptions}}\n  --model <selector>  目录模型选择器（例如，web/duckduckgo）\n  --recency <value>   时效性过滤器（受支持时）：{{recency}}\n  -l, --limit <n>     返回的最大结果数\n  --compact           渲染精简输出\n  -h, --help          显示此帮助\n\n{{headingQueryDirectives}}\n  site:/-site:  after:/before: (YYYY-MM-DD)  inurl:  intitle:  filetype:\n  "exact phrase"  -term  OR\n  在可用时映射到原生提供商过滤器，否则作为\n  宽松的后置过滤器应用（不匹配任何内容的约束会被放宽，而不是致命错误）。\n\n{{headingExamples}}\n  {{app}} q --model=web/duckduckgo "what\'s the color of the sky"\n  {{app}} q --model=openrouter/google/gemini-2.5-flash --recency=week "latest TypeScript changes"\n  {{app}} q \'transformer scaling site:arxiv.org after:2024 -site:reddit.com\'\n',
